/** Auxiliary contributor: tags field + setTags command. No workflow describe. */
export default {
  contribute() {
    return {
      fields: [{ key: "tags", label: "标签", type: "text" }],
      commands: [{ id: "setTags", label: "设标签", from: ["open", "done"] }],
    };
  },
  decide(data) {
    const { task, action, input } = data;
    if (action === "setTags") {
      if (!input || typeof input.tags !== 'string') {
        return {
          kind: "input-required",
          fields: [{ key: "tags", label: "标签" }]
        };
      }
      let newTags = input.tags.trim().toLowerCase();
      if (!newTags) {
        return { kind: "reject", message: "标签不能为空" };
      }
      return {
        kind: "commit",
        state: task.state,
        fields: { ...task.fields, tags: newTags },
      };
    }
    return { kind: "reject", message: "未知动作" };
  },
};

